package app.thawani

internal fun cards3(): List<Card> = listOf(
Card("p13","first_aid","الجروح القطعية العميقة أو بتر الإصبع","997","إسعاف جراحي عاجل — حفظ الجزء المبتور","d","في حال بتر إصبع أو جزء من طرف: لا تضع الجزء المبتور مباشرة فوق الثلج أو في الماء أبداً؛ بل لفه بشاش رطب، ثم ضعه داخل كيس بلاستيكي محكم، ثم ضع الكيس في ماء وثلج.",listOf("اضغط مباشرة بقوة على الجرح النازف بشاش معقم وارفع الطرف المصاب فوق مستوى القلب.","إذا كان هناك جسم مغروس في الجرح (قطعة زجاج كبيرة أو سكين): لا تسحبه أبداً لأن سحبه يسبب نزيفاً حاداً؛ ثبّته بلفائف شاش حوله واضغط على حواف الجرح.","لحفظ الجزء المبتور (مثل إصبع): اشطفه بلطف بمحلول ملحي دون فركه، ولفه بشاش معقم مبلل قليلاً.","ضع الجزء الملفوف داخل كيس بلاستيكي نظيف وأغلقه بإحكام، ثم ضع هذا الكيس داخل وعاء يحتوي على ماء بارد وثلج.","اتصل بـ 997 وتوجه فوراً للمستشفى مع اصطحاب الجزء المبتور المحفوظ."),listOf("لا تجعل الثلج يلامس الأنسجة المبتورة مباشرة حتى لا تتجمد الخلايا وتموت.","لا تسحب السكين أو الزجاج المغروس بعمق في الجسم."),listOf("كتابة اسم المصاب والوقت الدقيق للإصابة على الكيس الحافظ للجزء المبتور."),listOf("البيت","المدرسة","الاستراحة","التخييم","السفر"),listOf(Link("وزارة الصحة: الجروح","https://www.moh.gov.sa/healthawareness/educationalcontent/firstaid/pages/017.aspx")),listOf()),
Card("p14","kids_elderly","غصة الرضع (أقل من سنة)","997","حرج جداً — بروتوكول خاص بالرضع","c","للرضع أقل من عمر سنة: لا تضغط على البطن أبداً (ممنوع مناورة هيمليخ البطنية) لخطورة إصابة الكبد؛ استخدم 5 ضربات ظهرية + 5 ضغطات صدرية.",listOf("اجلس وضع الرضيع منبطحاً على وجهه فوق ساعدك (مع إسناد فكه ورأسه بكف يدك دون تغطية فمه) بحيث يكون رأسه أخفض من مستوى جسمه.","وجّه 5 ضربات حاسمة بكعب يدك الأخرى في منتصف الظهر بين لوحي الكتف.","إذا لم يخرج الجسم الغريب: اقلب الرضيع بحذر على ظهره فوق ساعدك الآخر مع بقاء رأسه منخفضاً.","ضع إصبعين في منتصف صدر الرضيع (أسفل خط الحلمتين مباشرة) ووجّه 5 ضغطات صدرية سريعة بعمق 4 سم تقريباً.","كرر التبديل بين (5 ضربات ظهرية و5 ضغطات صدرية) مع الاتصال بـ 997 حتى يخرج الجسم الغريب ويبدأ الرضيع بالبكاء أو التنفس."),listOf("لا تضغط على بطن الرضيع تحت سن السنة أبداً.","لا تمسك الرضيع من قدميه وتقلبه رأساً على عقب أو تهزه بعنف."),listOf("علامات غصة الرضيع الخطيرة: ازرقاق الشفاه والوجه، عدم القدرة على البكاء أو إصدار صوت، ضعف الحركة."),listOf("البيت","المدرسة","السفر","الاستراحة"),listOf(Link("جمعية القلب الأمريكية: إرشادات انسداد مجرى الهواء عند الرضيع (2025)","https://cpr.heart.org/-/media/CPR-Files/CPR-Guidelines-Files/2025-Algorithms/Algorithm-BLS-Infant-FBAO.pdf?sc_lang=en"),Link("وزارة الصحة: الغصة","https://www.moh.gov.sa/awarenessplateform/FirstAid/Pages/Choking.aspx")),listOf(Link("إسعاف المصاب بالغصة أو الاختناق · الهلال الأحمر السعودي","https://youtu.be/dZ9-i_UpjlA"))),
Card("p15","kids_elderly","تسمم الأطفال بالمنظفات أو الأدوية أو البطاريات","937","طوارئ سموم — لا تجبر الطفل على القيء","c","لا تجبر المصاب على التقيؤ أبداً (خصوصاً عند شرب المبيضات أو المنظفات الحارقة أو المشتقات النفطية) لأن المادة تحرق المريء مرة ثانية عند رجوعها.",listOf("أبعد المادة السامة عن الطفل فوراً، وافحص فمه لإزالة أي بقايا حبوب أو مسحوق بقطعة قماش مبللة.","اتصل فوراً بمركز استشارات السموم بوزارة الصحة على الرقم (937) أو الإسعاف (997) إذا كانت هناك أعراض خطيرة.","احتفظ بعلبة الدواء أو المنظف أمامك لإبلاغ الطبيب بالاسم العلمي الدقيق والتركيز والكمية التقديرية ووقت الابتلاع.","إذا لامست المادة الكيميائية الجلد أو العين: اغسل المنطقة فوراً بماء الصنبور الجاري الفاتر لمدة 15 دقيقة.","في حال ابتلاع بطارية دائرية صغيرة (Button Battery): توجه لأقرب طوارئ مستشفى فوراً لأنها تسبب حروقاً كهربائية للمريء خلال ساعتين."),listOf("لا تدخل إصبعك في حلق الطفل لإحداث القيء ولا تعطه ماءً وملحاً.","لا تعطِ الطفل حليباً أو ليموناً أو زيتاً لمعادلة المادة السامة إلا بتوجيه صريح من طبيب مركز السموم (937)."),listOf("تجهيز معلومات الطفل للطبيب: العمر، الوزن التقريبي، اسم المادة، الوقت منذ الابتلاع، الأعراض الحالية."),listOf("البيت","المدرسة","الاستراحة","السفر"),listOf(Link("وزارة الصحة: خدمة 937 واستشارات التسمم","https://www.moh.gov.sa/937/pages/default.aspx")),listOf()),
Card("p16","kids_elderly","سقوط كبار السن في المنزل","997","فحص دقيق قبل أي محاولة لرفع المصاب","w","لا تتسرع برفع كبير السن من الأرض فور سقوطه؛ افحصه أولاً بهدوء وتأكد من عدم وجود كسر في الحوض أو الفخذ أو إصابة بالرأس.",listOf("هدّئ من روع المصاب، واطلب منه البقاء مكانه لبضع دقائق لالتقاط أنفاسه وتقييم حالته.","اسأله عن وجود ألم شديد في الرأس أو الرقبة أو الظهر أو الورك، ولاحظ هل إحدى الساقين تبدو أقصر أو ملتفة للخارج (علامة كسر عنق الفخذ).","إذا وجد ألم حاد في الورك/الظهر أو ضرب رأسه بقوة (خصوصاً إذا كان يتناول مسيلات دم): لا ترفعه أبداً، غطِّه ببطانية وضع وسادة تحت رأسه واتصل بـ 997.","إذا تأكدت من سلامته تماماً وقدرته على تحريك أطرافه بدون ألم: قرّب كرسياً متيناً بجانبه، وساعده على الانقلاب لجانبه ثم الجلوس على يديه وركبتيه.","اجعله يضع يديه على مقعد الكرسي ويرفع نفسه بركبته الأقوى ليجلس على الكرسي، ثم افحص ضغط دمه وسكره."),listOf("لا تسحب كبير السن من ذراعيه أو تحت إبطيه لرفعه مباشرة من الأرض.","لا تتجاهل ضربات الرأس البسيطة لدى كبار السن الذين يتناولون أدوية السيولة (راقبهم لمدة 48 ساعة)."),listOf("تجهيز المنزل الوقائي: مقابض إسناد في دورة المياه، فرش مانع للانزلاق، وإضاءة ليلية تلقائية في الممر."),listOf("البيت","المدرسة","الاستراحة","السفر"),listOf(Link("وزارة الصحة: الكسور","https://www.moh.gov.sa/healthawareness/educationalcontent/firstaid/pages/007.aspx")),listOf()),
Card("p17","kids_elderly","الغرق والإنقاذ المائي في المسابح والاستراحات","997","حرج جداً — تأمين التنفس الفوري","c","في حالات الغرق يكون سبب توقف القلب هو نقص الأكسجين؛ لذا يبدأ الإنعاش بإعطاء 5 أنفاس إنقاذية أولاً ثم الضغطات الصدرية، ولا تضيع الوقت بمحاولة إخراج الماء من المعدة.",listOf("أخرج الغريق من الماء بأمان (مدّ له عصا أو طوق نجاة أولاً إذا كان واعياً) واطلب الاتصال الفوري بـ 997.","ضع المصاب على ظهره فوق أرض صلبة بجانب المسبح، وافتح مجرى الهواء بإمالة الرأس للخلف ورفع الذقن بحذر.","تحقق من التنفس خلال 10 ثوانٍ؛ إذا كان لا يتنفس: ابدأ فوراً بالإنعاش القلبي الرئوي (30 ضغطة صدرية متبوعة بنفسين إنقاذيين).","إذا تقيأ المصاب الماء أثناء الإنعاش: أمل رأسه وجسمه للجانب لثوانٍ لخروج السوائل ثم أعده لوضع الظهر وواصل الإنعاش.","انزع الملابس المبللة الباردة وغطِّ المصاب ببطانية جافة فور استعادته للوعي والتنفس."),listOf("لا تضغط على بطن الغريق لإخراج الماء من رئتيه أو معدته؛ فهذا يؤخر الإنعاش ويسبب استنشاق القيء.","لا تترك الطفل الذي تعرض لشبه غرق بدون فحص طبي بالمستشفى حتى لو بدا بخير (لخطر الغرق الثانوي خلال 24 ساعة)."),listOf("الغرق يحدث بصمت تام خلال أقل من 60 ثانية دون صراخ؛ المراقبة البصرية المباشرة للأطفال حول المسابح إلزامية."),listOf("البيت","الاستراحة","التخييم","السفر","المدرسة"),listOf(Link("وزارة الصحة: الغرق","https://www.moh.gov.sa/awarenessplateform/firstaid/pages/drowning.aspx")),listOf(Link("كيفية إنقاذ الغريق · الهلال الأحمر السعودي","https://youtu.be/M9scZtEfsBI"))),
Card("p18","kids_elderly","الحرارة الشديدة والتشنج الحراري للطفل","937","طوارئ أطفال — تبريد آمن وحماية مجرى الهواء","w","لا تضع الطفل المصاب بالحمى أو التشنج الحراري في ماء بارد جداً أو ثلج أبداً، لأن ذلك يسبب انقباض الأوعية الدموية ويرفع حرارة الأعضاء الداخلية.",listOf("إذا حدث تشنج حراري للطفل: ضعه على سطح آمن مبطن على جانبه (وضعية الإفاقة) لمنع اختناقه باللعاب.","خفف ملابس الطفل فوراً (اترك طبقة خفيفة واحدة) واحسب مدة التشنج بالساعة.","لا تعطِ الطفل أي خافض حرارة أو ماء عن طريق الفم أثناء التشنج؛ انتظر حتى يتوقف التشنج ويستيقظ تماماً.","استخدم كمادات ماء فاتر (بدرجة حرارة الغرفة) حول الرقبة وتحت الإبطين وبين الفخذين.","راجع الطوارئ أو اتصل بـ 997 إذا استمر التشنج أكثر من 5 دقائق، أو إذا كان عمر الرضيع أقل من 3 أشهر وحرارته 38 درجة فأكثر."),listOf("لا تستخدم الكحول الطبي أو الخل أو الماء المثلج لعمل كمادات للطفل.","لا تعطِ الأسبرين للأطفال أبداً لخفض الحرارة."),listOf("حساب جرعة خافض الحرارة بالمليجرام حسب وزن الطفل الدقيق وليس العمر فقط (عبر الاتصال بـ 937)."),listOf("البيت","المدرسة","الاستراحة","السفر"),listOf(),listOf())
)
